                          ),
                        ),
                        autofillHints: const [AutofillHints.password],
                        textInputAction: TextInputAction.done,
                        enabled: !_busy,
                        validator: _validatePassword,
                        onFieldSubmitted: (_) => _signInWithEmail(),
                      ),
                      CheckboxListTile(
                        key: const Key('login_remember_me'),
                        value: _remember,
                        onChanged: _busy
                            ? null
