    });

    testWidgets('remember me is checked by default', (tester) async {
      await tester.pumpWidget(_host(FakeAuthService()));

      final checkbox = tester.widget<Checkbox>(find.byType(Checkbox));
      expect(checkbox.value, isTrue);
    });
  });


